  1	import { newId } from "@egma/ids";
  2	
  3	import { db, type Queryable } from "../client.ts";
  4	import { EGMA_PROVIDED_PERSONAS } from "../persona-library/catalog.ts";
  5	import { organization, project } from "../schema/tenancy.ts";
  6	import { insertExpectedBehaviorsProjectGrader } from "./seeded-graders.ts";
  7	import type { Membership } from "./memberships.ts";
  8	import { insertMembership } from "./memberships.ts";
  9	
 10	/**
 11	 * Creating a customer is the one write that cannot take an `AuthContext`,
 12	 * because it is what brings the boundary into existence. It is safe on the same
 13	 * terms as the resolver: it reads nothing, it names no existing organization,
 14	 * and the only rows it can touch are the ones it just made.
 15	 *
 16	 * Signup either fully succeeds or fully fails. An account with an organization
 17	 * but no project is a developer with no way forward, a project with no default
 18	 * persona is a first test waiting on one, and a project with no grader is a
 19	 * first run nobody grades. The organization, its first project, the pointer to
 20	 * Egma's shared default persona, its expected-behaviors grader and the owner's
 21	 * membership are therefore one transaction.
 22	 */
 23	
 24	/**
 25	 * Everything a project needs to be a *usable* project, written in one
 26	 * transaction: the row itself, the pointer to Egma's shared default persona,
 27	 * and its seeded expected-behaviors grader. It creates no local
 28	 * copy of that persona; a customer fork is a separate, explicit authoring
 29	 * action.
 30	 *
 31	 * **One factory, two callers, and that is the whole reason it is a function.**
 32	 * Signup provisions the first project and an admin creates every one after it.
 33	 * Both paths create the same complete project. There is no smaller project
 34	 * shape without an active default persona or its seeded grader.
 35	 *
 36	 * It takes the transaction rather than opening one, because both callers have
 37	 * other rows to write in the same breath — an organization and a membership for
 38	 * one, nothing yet for the other — and a project that committed while its
 39	 * organization rolled back would be a project belonging to nobody.
 40	 */
 41	export type NewProjectRow = {
 42	  readonly projectId: string;
 43	  readonly organizationId: string;
 44	  readonly name: string;
 45	  readonly slug: string;
 46	  readonly description: string | null;
 47	  readonly revision: string;
 48	  /** Nullable, because a project can be created by nobody — a seeded one. */
 49	  readonly createdBy: string | null;
 50	};
 51	
 52	export async function insertProject(
 53	  on: Queryable,
 54	  input: NewProjectRow,
 55	): Promise<void> {
 56	  await on.insert(project).values({
 57	    id: input.projectId,
 58	    organizationId: input.organizationId,
 59	    name: input.name,
 60	    slug: input.slug,
 61	    description: input.description,
 62	    revision: input.revision,
 63	    defaultPersonaId: EGMA_PROVIDED_PERSONAS.defaultPersona,
 64	    createdBy: input.createdBy,
 65	  });
 66	
 67	  // The project's expected-behavior grading, in the same transaction as
 68	  // everything else: one project grader with fixed all-simulations scope.
 69	  // It holds project policy, not grader code. The behaviors somebody wrote on
 70	  // their first test are graded because this row exists. There is no separate
 71	  // `required`, `mandatory`, or running-copy field.
 72	  await insertExpectedBehaviorsProjectGrader(on, {
 73	    organizationId: input.organizationId,
 74	    projectId: input.projectId,
 75	  });
 76	
 77	}
 78	
 79	export type NewOrganization = {
 80	  /** The person the organization is being created for. They become its admin. */
 81	  readonly ownerUserId: string;
 82	  readonly organizationName: string;
 83	  readonly organizationSlug: string;
 84	  readonly projectName: string;
 85	  readonly projectSlug: string;
 86	};
 87	
 88	export type ProvisionedOrganization = {
 89	  readonly organizationId: string;
 90	  readonly projectId: string;
 91	  readonly membership: Membership;
 92	};
 93	
 94	export async function provisionOrganization(
 95	  input: NewOrganization,
 96	): Promise<ProvisionedOrganization> {
 97	  const organizationId = newId("org");
 98	  const projectId = newId("prj");
 99	
100	  return db().transaction(async (tx) => {
101	    await tx.insert(organization).values({
102	      id: organizationId,
103	      name: input.organizationName,
104	      slug: input.organizationSlug,
105	    });
106	
107	    // The one project factory, on the same terms an admin's Settings create
108	    // gets: the row, the shared default persona pointer, and seeded grader.
109	    // Signing up and creating a second project
110	    // are the same act performed by different people, so they are the same
111	    // write.
112	    await insertProject(tx, {
113	      projectId,
114	      organizationId,
115	      name: input.projectName,
116	      slug: input.projectSlug,
117	      description: null,
118	      revision: newId("rev"),
119	      createdBy: input.ownerUserId,
120	    });
121	
122	    // Everyone is an admin in v1 and roles are invisible, but the permission
123	    // map is real from the first commit. The creator of an organization is its
124	    // admin; anyone else arrives through an invitation.
125	    const membership = await insertMembership(tx, {
126	      organizationId,
127	      userId: input.ownerUserId,
128	      role: "admin",
129	      createdBy: input.ownerUserId,
130	    });
131	
132	    return { organizationId, projectId, membership };
133	  });
134	}

