363	    if (checked === undefined) {
364	      checked = verifyRetellChatAgent(
365	        apiKey,
366	        agentId,
367	        retellFetch,
368	        Math.max(1, responseDeadline - Date.now() - 500),
369	      );
370	      retellTargets.set(connection.connectionId, checked);
371	    }
372	    const target = await checked;
373	    if (target.kind === "blocked") {
374	      return { unbuildable: target.message };
375	    }
376	    if (target.kind === "retryable") {
377	      return { retryable: target.message };
378	    }
379	  }
380	
381	  // Read the live carrier route only for `phone_number`. A Retell chat or
382	  // LiveKit room claim must not carry a SIP password it cannot use.
383	  const platform =
384	    connectionTypeUsesPlatformCarrier(connection.connectionType)
385	      ? platformBlock(await resolvePlatformSettings(claim.auth))
386	      : undefined;
387	
388	  if (!runs.has(claim.runId)) {
389	    runs.set(claim.runId, await getRun(claim.auth, claim.runId));
390	  }
391	  const run = runs.get(claim.runId);
392	  if (run === undefined) {
393	    return { unbuildable: "its run could not be read" };
394	  }
395	
396	  // Resolved here and nowhere else. `resolveMockTools` is the one place a
397	  // project default and a test override are folded together, and the
398	  // snapshot it folds was frozen when the run was created — so every
399	  // simulation in one run is served one world, and a mock tool edited
400	  // mid-run tears nothing. The simulator receives the answers already
401	  // decided, exactly as it receives everything else: flattened, with
402	  // nothing left to look up and nothing left to choose between.
403	  const mockTools = resolveMockTools(
404	    evidence.mockToolSnapshot,
405	    claim.testVersionId,
406	  ).map((mock) => ({
407	    tool_name: mock.toolName,
408	    answer: mock.answer,
409	    delay_milliseconds: mock.delayMilliseconds,
410	  }));
411	
412	  let models: Record<string, unknown>;
413	  try {
414	    // The source loads here, once per simulation work order. Persona choices
415	    // are pinned; credentials are current. A rotated AWS bundle therefore
416	    // reaches the next claimed simulation without changing the persona or
417	    // restarting either service.
418	    models = await modelsBlock(
419	      claim.modality,
420	      personaVersion.models,
421	      providerCredentials,
422	    );
423	  } catch (fault) {
424	    if (fault instanceof ProviderCredentialSourceUnavailableError) {
425	      return {
426	        retryable:
427	          "the current model-provider credential bundle could not be read",
428	      };
429	    }
430	    throw fault;
431	  }
432	
433	  const spec = {
434	    contract_version: CONTRACT_VERSION,
435	    simulation_id: claim.id,
436	    modality: claim.modality,
437	    connection: {
