430	 * predicate that filtered them out here would make an archived persona
431	 * unreachable by the one operation that exists to bring them back.
432	 */
433	function thePersona(auth: AuthContext, id: string): SQL {
434	  return readablePersona(auth, eq(persona.id, id));
435	}
436	
437	export type SeededPersona = {
438	  readonly id: string;
439	  readonly name: string;
440	  readonly version: number;
441	  readonly versionId: string;
442	};
443	
444	function currentCatalogVersion(entry: EgmaProvidedPersona) {
445	  const current = entry.versions.at(-1);
446	  if (current === undefined) {
447	    throw new Error(`Egma-provided persona ${entry.id} has no version`);
448	  }
449	  entry.versions.forEach((version, index) => {
450	    if (version.version !== index + 1) {
451	      throw new Error(
452	        `Egma-provided persona ${entry.id} version ${version.id} must be number ${index + 1}`,
453	      );
454	    }
455	    validateTraits(version.traits);
456	    validPersonaModels(version.models);
457	  });
458	  return current;
459	}
460	
461	/**
462	 * Put the personas Egma provides in the database without rewriting a version.
463	 * Identity metadata and the current pointer may move; version rows are insert
464	 * only and are checked byte for byte when their fixed id already exists.
465	 */
466	/** @internal Called only by the deployment seeder outside the access surface. */
467	export async function seedPersonaLibraryInternal(
468	  catalog: readonly EgmaProvidedPersona[] = PERSONA_LIBRARY_CATALOG,
469	): Promise<readonly SeededPersona[]> {
470	  if (catalog.length === 0) return [];
471	
