  1	/**
  2	 * The model combinations this release can execute.
  3	 *
  4	 * A catalog entry is an adapter contract, not a suggestion. Provider and
  5	 * model are kept together because an adapter supports the pair. Accepting the
  6	 * two fields independently is what allowed a realtime OpenAI model to reach
  7	 * the segmented transcription endpoint in production.
  8	 */
  9	export const MODEL_JOBS = ["llm", "stt", "tts"] as const;
 10	export type ModelJob = (typeof MODEL_JOBS)[number];
 11	
 12	export const MODEL_PROVIDERS = ["openai", "deepgram", "cartesia"] as const;
 13	export type ModelProvider = (typeof MODEL_PROVIDERS)[number];
 14	
 15	export type ProviderCatalogEntry = {
 16	  readonly provider: ModelProvider;
 17	  readonly job: ModelJob;
 18	  readonly model: string;
 19	  readonly label: string;
 20	  readonly recommendedVoiceId?: string;
 21	  readonly recommendedSpeed?: number;
 22	};
 23	
 24	export const PROVIDER_CATALOG = [
 25	  {
 26	    provider: "openai",
 27	    job: "llm",
 28	    model: "gpt-4o-mini",
 29	    label: "OpenAI",
 30	  },
 31	  {
 32	    // This is the realtime transcription adapter. It must never be sent to
 33	    // OpenAI's segmented /v1/audio/transcriptions endpoint.
 34	    provider: "openai",
 35	    job: "stt",
 36	    model: "gpt-live-transcribe",
 37	    label: "OpenAI",
 38	  },
 39	  {
 40	    provider: "deepgram",
 41	    job: "stt",
 42	    model: "nova-3-general",
 43	    label: "Deepgram",
 44	  },
 45	  {
 46	    provider: "cartesia",
 47	    job: "tts",
 48	    model: "sonic-3.5",
 49	    label: "Cartesia",
 50	    recommendedVoiceId: "5ee9feff-1265-424a-9d7f-8e4d431a12c7",
 51	    recommendedSpeed: 1,
 52	  },
 53	  {
 54	    provider: "openai",
 55	    job: "tts",
 56	    model: "gpt-4o-mini-tts",
 57	    label: "OpenAI",
 58	    recommendedVoiceId: "alloy",
 59	    recommendedSpeed: 1,
 60	  },
 61	] as const satisfies readonly ProviderCatalogEntry[];
 62	
 63	export const PROVIDERS_BY_JOB: {
 64	  readonly [Job in ModelJob]: readonly ProviderCatalogEntry[];
 65	} = {
 66	  llm: PROVIDER_CATALOG.filter((entry) => entry.job === "llm"),
 67	  stt: PROVIDER_CATALOG.filter((entry) => entry.job === "stt"),
 68	  tts: PROVIDER_CATALOG.filter((entry) => entry.job === "tts"),
 69	};
 70	
 71	/** The first supported pair for each job is the release default. */
 72	export const RECOMMENDED_ENTRY: {
 73	  readonly [Job in ModelJob]: ProviderCatalogEntry;
 74	} = {
 75	  llm: firstEntryFor("llm"),
 76	  stt: firstEntryFor("stt"),
 77	  tts: firstEntryFor("tts"),
 78	};
 79	
 80	export function isModelProvider(provider: string): provider is ModelProvider {
 81	  return MODEL_PROVIDERS.some((known) => known === provider);
 82	}
 83	
 84	export function catalogEntry(
 85	  job: ModelJob,
 86	  provider: string,
 87	  model: string,
 88	): ProviderCatalogEntry | undefined {
 89	  return PROVIDERS_BY_JOB[job].find(
 90	    (entry) => entry.provider === provider && entry.model === model,
 91	  );
 92	}
 93	
 94	function firstEntryFor(job: ModelJob): ProviderCatalogEntry {
 95	  const first = PROVIDERS_BY_JOB[job][0];
 96	  if (first === undefined) {
 97	    throw new Error(`the provider catalog ships no ${job} adapter`);
 98	  }
 99	  return first;
100	}
  1	import { UnprocessableInputError } from "../access/errors.ts";
  2	import {
  3	  PROVIDERS_BY_JOB,
  4	  RECOMMENDED_ENTRY,
  5	  catalogEntry,
  6	  type ModelJob,
  7	  type ModelProvider,
  8	} from "./catalog.ts";
  9	
 10	export type ModelSelection = {
 11	  readonly provider: ModelProvider;
 12	  readonly model: string;
 13	};
 14	
 15	export type SpeechSelection = ModelSelection & {
 16	  readonly voiceId: string;
 17	  readonly speed: number;
 18	};
 19	
 20	/** The complete executable model choice owned by one persona version. */
 21	export type PersonaModels = {
 22	  readonly llm: ModelSelection;
 23	  readonly stt: ModelSelection;
 24	  readonly tts: SpeechSelection;
 25	};
 26	
 27	export type GraderModel = ModelSelection;
 28	
 29	export const SPEED_RANGE = { slowest: 0.6, fastest: 1.5 } as const;
 30	
 31	function validSelection(
 32	  job: ModelJob,
 33	  value: unknown,
 34	  accepted: readonly string[] = ["provider", "model"],
 35	): ModelSelection {
 36	  if (typeof value !== "object" || value === null || Array.isArray(value)) {
 37	    throw new UnprocessableInputError(`the ${job} selection must be an object`);
 38	  }
 39	  const unsupported = Object.keys(value).filter(
 40	    (key) => !accepted.includes(key),
 41	  );
 42	  if (unsupported.length > 0) {
 43	    throw new UnprocessableInputError(
 44	      `the ${job} selection has unsupported fields ${unsupported.join(", ")}`,
 45	    );
 46	  }
 47	  const { provider, model } = value as Record<string, unknown>;
 48	  if (typeof provider !== "string" || typeof model !== "string") {
 49	    throw new UnprocessableInputError(
 50	      `the ${job} selection needs a provider and model`,
 51	    );
 52	  }
 53	  const entry = catalogEntry(job, provider, model.trim());
 54	  if (entry === undefined) {
 55	    const supported = PROVIDERS_BY_JOB[job]
 56	      .map((known) => `${known.provider}/${known.model}`)
 57	      .join(", ");
 58	    throw new UnprocessableInputError(
 59	      `"${provider}/${model}" is not a supported ${provider} ${job} model; expected one of ${supported}`,
 60	    );
 61	  }
 62	  return { provider: entry.provider, model: entry.model };
 63	}
 64	
 65	function validSpeech(value: unknown): SpeechSelection {
 66	  const selection = validSelection("tts", value, [
 67	    "provider",
 68	    "model",
 69	    "voiceId",
 70	    "speed",
 71	  ]);
 72	  const { voiceId, speed } = value as Record<string, unknown>;
 73	  if (typeof voiceId !== "string" || voiceId.trim() === "") {
 74	    throw new UnprocessableInputError(
 75	      "the tts selection needs a voice id from its provider",
 76	    );
 77	  }
 78	  if (
 79	    typeof speed !== "number" ||
 80	    !Number.isFinite(speed) ||
 81	    speed < SPEED_RANGE.slowest ||
 82	    speed > SPEED_RANGE.fastest
 83	  ) {
 84	    throw new UnprocessableInputError(
 85	      `speaking speed must be between ${SPEED_RANGE.slowest} and ${SPEED_RANGE.fastest}`,
 86	    );
 87	  }
 88	  return { ...selection, voiceId: voiceId.trim(), speed };
 89	}
 90	
 91	export function validPersonaModels(value: unknown): PersonaModels {
 92	  if (typeof value !== "object" || value === null || Array.isArray(value)) {
 93	    throw new UnprocessableInputError("persona models must be an object");
 94	  }
 95	  const held = value as Record<string, unknown>;
 96	  const unsupported = Object.keys(held).filter(
 97	    (key) => !["llm", "stt", "tts"].includes(key),
 98	  );
 99	  if (unsupported.length > 0) {
100	    throw new UnprocessableInputError(
101	      `persona models have unsupported fields ${unsupported.join(", ")}`,
102	    );
103	  }
104	  return {
105	    llm: validSelection("llm", held.llm),
106	    stt: validSelection("stt", held.stt),
107	    tts: validSpeech(held.tts),
108	  };
109	}
110	
111	export function validGraderModel(value: unknown): GraderModel {
112	  return validSelection("llm", value);
113	}
114	
115	function sameSelection(a: ModelSelection, b: ModelSelection): boolean {
116	  return a.provider === b.provider && a.model === b.model;
117	}
118	
119	export function samePersonaModels(a: PersonaModels, b: PersonaModels): boolean {
120	  return (
121	    sameSelection(a.llm, b.llm) &&
122	    sameSelection(a.stt, b.stt) &&
123	    sameSelection(a.tts, b.tts) &&
124	    a.tts.voiceId === b.tts.voiceId &&
125	    a.tts.speed === b.tts.speed
126	  );
127	}
128	
129	export function sameGraderModel(a: GraderModel, b: GraderModel): boolean {
130	  return sameSelection(a, b);
131	}
132	
133	/** Read required immutable persona models. Missing or invalid data is corrupt. */
134	export function personaModelsFromRow(
135	  value: unknown,
136	  versionId: string,
137	): PersonaModels {
138	  try {
139	    return validPersonaModels(value);
140	  } catch {
141	    throw new Error(
142	      `version ${versionId} holds persona models in a shape Egma never writes; the row needs repairing before anybody can read it`,
143	    );
144	  }
145	}
146	
147	export function graderModelFromRow(
148	  value: unknown,
149	  versionId: string,
150	): GraderModel {
151	  try {
152	    return validGraderModel(value);
153	  } catch {
154	    throw new Error(
155	      `version ${versionId} holds a grader model in a shape Egma never writes; the row needs repairing before anybody can read it`,
156	    );
157	  }
158	}
159	
160	function recommendedSelection(job: ModelJob): ModelSelection {
161	  const entry = RECOMMENDED_ENTRY[job];
162	  return { provider: entry.provider, model: entry.model };
163	}
164	
165	function recommendedSpeech(): SpeechSelection {
166	  const entry = RECOMMENDED_ENTRY.tts;
167	  if (
168	    entry.recommendedVoiceId === undefined ||
169	    entry.recommendedSpeed === undefined ||
170	    entry.recommendedSpeed < SPEED_RANGE.slowest ||
171	    entry.recommendedSpeed > SPEED_RANGE.fastest
172	  ) {
173	    throw new Error(
174	      "the recommended TTS catalog entry needs a voice and an in-range speed",
175	    );
176	  }
177	  return {
178	    provider: entry.provider,
179	    model: entry.model,
180	    voiceId: entry.recommendedVoiceId,
181	    speed: entry.recommendedSpeed,
182	  };
183	}
184	
185	export const RECOMMENDED_PERSONA_MODELS: PersonaModels = {
186	  llm: recommendedSelection("llm"),
187	  stt: recommendedSelection("stt"),
188	  tts: recommendedSpeech(),
189	};
190	
191	export const RECOMMENDED_GRADER_MODEL: GraderModel =
192	  recommendedSelection("llm");

