        .insert(persona)
        .values({
          id: entry.id,
          organizationId: null,
          projectId: null,
          name: entry.name,
          description: entry.description,
          currentVersionId: current.id,
          createdBy: null,
          createdAt: entry.versions[0]?.createdAt ?? current.createdAt,
          updatedAt: entry.versions[0]?.createdAt ?? current.createdAt,
