              .where(
                and(
                  eq(persona.id, entry.id),
                  isNull(persona.organizationId),
                  sql`(${persona.name}, ${persona.description}, ${persona.currentVersionId}) is distinct from (${entry.name}, ${entry.description}, ${current.id})`,
