import { readFileSync } from "node:fs";

import { Ajv2020, type ValidateFunction } from "ajv/dist/2020.js";
import ajvFormats from "ajv-formats";

// ajv-formats ships CommonJS whose module.exports is the plugin function
// itself. Under NodeNext, the default import is typed as its namespace and
// the namespace's default is that callable, with its declared type intact.
const addFormats = ajvFormats.default;

/**
 * The contract's documents, as TypeScript can check them.
 *
 * The schemas under `schemas/` are the authority, read from disk because the
 * other reader of those bytes is not TypeScript — the simulator compiles the
 * same files (`contract.py`) and holds every claimed spec to the spec schema.
 * This is the control plane's half of the same guarantee, both ways round: a
 * spec is checked *before it is sent*, so a document that does not speak the
 * contract is a fault caught on the sending side rather than a refusal the
 * simulator has to explain back — and a report is checked *as it arrives*,
 * so nothing off the wire reaches a lifecycle write without having proven it
 * speaks the contract the simulator's own check already applied on the way
 * out.
 *
 * The answer is a list of complaints rather than a thrown violation, because
 * the caller's next move is not an exception's: one unbuildable spec is
 * skipped and said out loud, and the rest of the batch still goes; one
 * refused report is answered with its complaints, and the simulator's log
 * shows the same sentences its own check would have raised. Each complaint
 * names the place and the problem — `/modality: must be equal to one of the
 * allowed values` — in the same shape the simulator's check logs, so the two
 * sides of the wire read alike in two languages.
 */

/**
 * Compiled once each, on first use rather than at import, so loading the
 * package for its measure catalog never pays for — or fails on — schema
 * compilation. Compiling is itself part of the check: a schema that is not
 * valid 2020-12 fails loudly here, rather than quietly accepting everything.
 */
function compileFromDisk(schemaFile: string): ValidateFunction {
  const ajv = new Ajv2020({ strict: true, allErrors: true });
  addFormats(ajv);
  const schema: unknown = JSON.parse(
    readFileSync(new URL(`../schemas/${schemaFile}`, import.meta.url), "utf8"),
  );
  return ajv.compile(schema as Record<string, unknown>);
}

let compiledSpec: ValidateFunction | undefined;
let compiledReport: ValidateFunction | undefined;

/**
 * Everything wrong with a document by one validator's lights, or nothing.
 * `allErrors`, deliberately, so one answer says everything wrong at once
 * rather than one complaint per attempt.
 */
function complaintsFrom(
  validate: ValidateFunction,
  document: unknown,
): readonly string[] {
  if (validate(document)) return [];
  return (validate.errors ?? []).map(
    (error) => `${error.instancePath}: ${error.message ?? "does not validate"}`,
  );
}

/**
 * Everything wrong with one would-be spec document, or nothing.
 *
 * An empty answer is the green light: the document speaks the spec direction
 * of the contract and a simulator holding this contract version will accept
 * it. Anything else is the full list, because a log line about a skipped
 * simulation should say everything wrong with it at once rather than one
 * complaint per attempt that will never be retried.
 */
export function specComplaints(document: unknown): readonly string[] {
  compiledSpec ??= compileFromDisk("simulation-spec.v3.schema.json");
  return complaintsFrom(compiledSpec, document);
}

/**
 * Everything wrong with one arrived report document, or nothing.
 *
 * An empty answer means the document speaks the report direction of the
 * contract, and only then does the control plane read anything out of it —
 * which is also where the vocabulary line is held: the endings a caller may
 * report are the ones the schema enumerates, so the platform's own words
 * (`orphaned` is the sweep's, `dispatch_failed` the claim path's) are refused
 * here as documents rather than reasoned about as states.
 */
export function reportComplaints(document: unknown): readonly string[] {
  compiledReport ??= compileFromDisk("simulation-report.v1.schema.json");
  return complaintsFrom(compiledReport, document);
}
/**
 * The simulation contract, as TypeScript can hold it.
 *
 * Almost all of this contract is JSON — two schemas under `schemas/`, read by
 * both sides from disk, because the other reader of those bytes is not
 * TypeScript. What is here is what the control plane checks on its own side
 * of the wire: the measure catalog, which a grader's write door refuses an
 * unknown measure against, the spec check every outgoing claim answer passes
 * through before a byte of it is sent, the report check every arriving
 * document passes through before a byte of it is believed, and the one
 * derivation that turns a simulation id into the trace its spans are filed
 * under.
 */

export { reportComplaints, specComplaints } from "./documents.ts";

export {
  simulationIdOfTrace,
  traceIdOfSimulation,
} from "./trace-identity.ts";

export {
  bannedWordIn,
  BANNED_MOCK_TOOL_WORDS,
  type BannedWord,
  type BannedWordFound,
} from "./vocabulary.ts";

export {
  catalogedMeasure,
  isCatalogedMeasure,
  isSpanDerivedMeasure,
  measureAccepts,
  CATALOGED_MEASURES,
  MEASURE_AGGREGATIONS,
  MEASURE_CATALOG,
  MEASURE_CATALOG_DOCUMENT,
  MEASURE_CATALOG_VERSION,
  SPAN_DERIVED_MEASURE_CATALOG,
  SPAN_DERIVED_MEASURES,
  SPAN_RULES,
  type CatalogedMeasure,
  type MeasureAggregation,
  type MeasureFromSpans,
  type MeasureOrigin,
  type MeasureShape,
  type MeasureSource,
  type SpanRule,
} from "./measures.ts";
"""The simulation contract, as the simulator sees it.

The two JSON Schemas under ``packages/simulation-contract`` are the one
meeting point between the TypeScript control plane and this service. This
module locates that package, compiles both schemas once, and offers the two
validation directions: a claimed spec is refused if it does not speak the
contract, and every outgoing report is held to the report schema before a
byte of it leaves the process.

The schemas are read from the contract package rather than vendored here,
deliberately: one shared artifact, two readers. Inside the repository the
package sits a fixed walk up from this file; a deployment that lays files
out differently points ``EGMA_SIMULATION_CONTRACT_DIR`` at a directory
holding ``schemas/`` and ``fixtures/``.
"""

from __future__ import annotations

import json
import os
from functools import cache
from pathlib import Path

from jsonschema import Draft202012Validator, FormatChecker

CONTRACT_DIR_ENV = "EGMA_SIMULATION_CONTRACT_DIR"

SPEC_SCHEMA_FILENAME = "simulation-spec.v3.schema.json"
REPORT_SCHEMA_FILENAME = "simulation-report.v1.schema.json"

# The endings a failed simulation may carry, spelled here because this is
# where the contract's vocabulary lives — the schema is the authority and
# this module is the one that reads it. Naming them once means the code
# that decides which one a failure deserves and the code that writes it
# onto a report cannot drift into two different spellings.
ERROR = "error"
"""The simulator hit a fault it could not conduct through."""

AGENT_NEVER_JOINED = "agent_never_joined"
"""The way in opened and no agent turned up, so nothing was tested."""

NOT_ANSWERED = "not_answered"
"""The simulator reached out and nothing picked up, so nothing was tested."""


class ContractViolation(Exception):
    """A document does not speak the simulation contract.

    Carries which direction refused it and every complaint the schema had,
    so a log line names the exact place a document went wrong.
    """

    def __init__(self, direction: str, complaints: list[str]):
        self.direction = direction
        self.complaints = complaints
        super().__init__(f"{direction} document violates the contract: {complaints}")


def contract_dir() -> Path:
    """Where the contract package lives.

    ``EGMA_SIMULATION_CONTRACT_DIR`` wins when set; otherwise walk up from
    this file looking for ``packages/simulation-contract``, which finds the
    package from anywhere inside the repository checkout.
    """
    named = os.environ.get(CONTRACT_DIR_ENV)
    if named:
        directory = Path(named)
        if not (directory / "schemas").is_dir():
            raise FileNotFoundError(
                f"{CONTRACT_DIR_ENV}={named} has no schemas/ directory"
            )
        return directory

    for ancestor in Path(__file__).resolve().parents:
        candidate = ancestor / "packages" / "simulation-contract"
        if (candidate / "schemas").is_dir():
            return candidate

    raise FileNotFoundError(
        "packages/simulation-contract not found above "
        f"{Path(__file__).resolve()}; set {CONTRACT_DIR_ENV}"
    )


def _load_schema(filename: str) -> dict:
    with open(contract_dir() / "schemas" / filename, encoding="utf-8") as handle:
        return json.load(handle)


@cache
def spec_contract_version() -> int:
    """The one spec version this simulator can read.

    Read it from the schema the simulator validates with. The claim client must
    not keep a second version number that can drift from the document parser.
    """
    schema = _load_schema(SPEC_SCHEMA_FILENAME)
    try:
        version = schema["properties"]["contract_version"]["const"]
    except (KeyError, TypeError) as error:
        raise ValueError(
            f"{SPEC_SCHEMA_FILENAME} does not declare one contract version"
        ) from error
    if not isinstance(version, int) or isinstance(version, bool):
        raise ValueError(
            f"{SPEC_SCHEMA_FILENAME} declares a non-integer contract version"
        )
    return version


SCHEMA_OF = {
    "spec": SPEC_SCHEMA_FILENAME,
    "report": REPORT_SCHEMA_FILENAME,
}


@cache
def validator(direction: str) -> Draft202012Validator:
    """The compiled validator for one direction, built once per process.

    Compiling is part of the guarantee: a schema that is not valid
    2020-12 fails here, at import of the first document, rather than
    quietly accepting everything.
    """
    schema = _load_schema(SCHEMA_OF[direction])
    Draft202012Validator.check_schema(schema)
    return Draft202012Validator(schema, format_checker=FormatChecker())


def spec_validator() -> Draft202012Validator:
    return validator("spec")


def report_validator() -> Draft202012Validator:
    return validator("report")


def _complaints(direction: str, document: object) -> list[str]:
    def flatten(errors) -> list[str]:
        flat: list[str] = []
        for error in errors:
            if error.context:
                flat.extend(flatten(error.context))
            else:
                place = "".join(f"/{part}" for part in error.absolute_path)
                flat.append(f"{place}: {error.message}")
        return flat

    return flatten(validator(direction).iter_errors(document))


def validate(direction: str, document: object) -> None:
    """Refuse a document that does not speak the contract in its direction."""
    complaints = _complaints(direction, document)
    if complaints:
        raise ContractViolation(direction, complaints)


def validate_spec(document: object) -> None:
    """Refuse a claimed spec that does not speak the contract."""
    validate("spec", document)


def validate_report(document: object) -> None:
    """Refuse an outgoing report that does not speak the contract."""
    validate("report", document)

/** The one clean-cut contract this control plane and simulator speak. */
const CONTRACT_VERSION = 3;

type Body = Record<string, unknown>;

/**
 * The current carrier route, or no platform block when this deployment has no
 * phone route. Model, speech, voice, VAD and media facts cannot enter here.
 */
function platformBlock(
  held: PlatformSettingValues,
): Record<string, unknown> | undefined {
  // Model and speech fields cannot enter this document from the platform
  // store. The persona version owns those choices and the credential source
  // below authorizes them. The platform owns only the shared phone route.
  const carrier = onlyWhatIsHeld({
    trunk_address: held.carrier_trunk_address,
    trunk_number: held.carrier_trunk_number,
    trunk_username: held.carrier_trunk_username,
    trunk_password: held.carrier_trunk_password,
  });

  const platform = onlyWhatIsHeld({ carrier });
  // No carrier means no platform block, not a carrier made of empty fields.
  return platform === undefined ? undefined : platform;
}

/**
 * The pinned persona selections with only the credentials this simulation
 * can use.
 *
 * The source is loaded exactly once in this function. A voice simulation gets
 * keys for all three legs; a chat simulation gets only its LLM key. The whole
 * current bundle never crosses the claim door.
 */
async function modelsBlock(
  modality: SimulationClaim["modality"],
  models: PersonaModels,
  source: ProviderCredentialSource,
): Promise<Record<string, unknown>> {
  const credentials = await source.load();
  const keyFor = (
    provider: PersonaModels["llm"]["provider"],
  ): string => credentialFor(credentials, provider);
  const speechKey = (
    provider: PersonaModels["llm"]["provider"],
  ): Record<string, string> =>
    modality === "voice" ? { key: keyFor(provider) } : {};

  return {
    llm: {
      provider: models.llm.provider,
      model: models.llm.model,
      key: keyFor(models.llm.provider),
    },
    stt: {
      provider: models.stt.provider,
      model: models.stt.model,
      ...speechKey(models.stt.provider),
    },
    tts: {
      provider: models.tts.provider,
      model: models.tts.model,
      voice_id: models.tts.voiceId,
      speed: models.tts.speed,
      ...speechKey(models.tts.provider),
    },
  };
}

/** One block with its absent fields dropped, or nothing where none is held. */
function onlyWhatIsHeld<T>(
  fields: Record<string, T | undefined>,
): Record<string, T> | undefined {
  const present = Object.entries(fields).filter(
    ([, value]) => value !== undefined,
  );
  return present.length === 0
    ? undefined
    : (Object.fromEntries(present) as Record<string, T>);
}

